// ─── Derived views used by the dashboard ─────────────────────────────────────

export const featuredCompanies = companies.filter((c) => c.featured);

export const hubCompanies = companies.filter((c) => c.hasHub);

/** First A–Z letter bucket for a company ("#" for non-alpha). */
export function companyLetter(c: Company): string {
  const ch = c.name.replace(/^["'(]/, '').charAt(0).toUpperCase();
  return /[A-Z]/.test(ch) ? ch : '#';
}

export const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
